// Determine which day this is running (Wed=3, Thu=4, Fri=5)
const now = new Date();
const dayOfWeek = now.getDay();

let dayName = "Unknown";
let reminderType = "";

if (dayOfWeek === 3) {
  dayName = "Wednesday";
  reminderType = "First Reminder";
} else if (dayOfWeek === 4) {
  dayName = "Thursday";
  reminderType = "Second Reminder";
} else if (dayOfWeek === 5) {
  dayName = "Friday";
  reminderType = "Final Reminder";
}

// Calculate Monday 00:00 of current week
const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
const monday = new Date(now);
monday.setDate(now.getDate() + mondayOffset);
monday.setHours(0, 0, 0, 0);

// Get week number for tracking
const weekNumber = Math.ceil(((now - new Date(now.getFullYear(), 0, 1)) / 86400000 + 1) / 7);

return [
  {
    json: {
      currentDay: dayName,
      dayOfWeek: dayOfWeek,
      reminderType: reminderType,
      mondayDate: monday.toISOString().split('T')[0],
      todayDate: now.toISOString().split('T')[0],
      weekNumber: weekNumber,
      year: now.getFullYear()
    }
  }
];

// Reporter name to email mapping
const reporterEmails = {
  "Reporter C": "reporter.c@example.com",
  "Reporter A": "reporter.a@example.com",
  "Reporter B": "reporter.b@example.com"
};

// Boss emails for CC
const bossEmails = [
  "pm-group@example.com",
  "project.manager@example.com"
];

const contextData = items[0].json;

return [
  {
    json: {
      ...contextData,
      reporterEmails: reporterEmails,
      bossEmails: bossEmails,
      reporterNames: Object.keys(reporterEmails)
    }
  }
];

// FIXED: Detect Inactive Reporters - Corrected Logic
const jiraResponse = items[0].json;
const issues = jiraResponse.issues || [];

// Get context from previous node
const contextItem = $node["Reporter Email Mapping"].json;
const allReporters = contextItem.reporterNames;
const reporterEmails = contextItem.reporterEmails;

// Helper function: normalize names for comparison
function normalizeName(name) {
  if (!name) return '';
  return name.toLowerCase().trim().replace(/\s+/g, ' ');
}

// Get unique reporters who have activity (based on being assigned to updated issues)
const activeReportersNormalized = new Set();

issues.forEach(issue => {
  // Check the assignee field (who the issue is assigned to)
  const assigneeName = issue.fields?.assignee?.displayName;
  if (assigneeName) {
    const normalized = normalizeName(assigneeName);
    activeReportersNormalized.add(normalized);
  }
});

// Identify inactive reporters - FIXED: Use separate loop to avoid duplicates
const inactiveReporters = [];
const activeReporters = [];

allReporters.forEach(reporterName => {
  const normalized = normalizeName(reporterName);
  if (activeReportersNormalized.has(normalized)) {
    activeReporters.push(reporterName);
  } else {
    inactiveReporters.push(reporterName);
  }
});

return [
  {
    json: {
      ...contextItem,
      activeReporters: activeReporters,
      inactiveReporters: inactiveReporters,
      totalIssues: issues.length,
      activitySummary: issues.map(i => ({
        assignee: i.fields?.assignee?.displayName,
        summary: i.fields?.summary,
        updated: i.fields?.updated
      }))
    }
  }
];

// Check who already received reminders this week
const sheetData = items;
const contextData = $node["Detect Inactive Reporters"].json;
const inactiveReporters = contextData.inactiveReporters;
const currentWeek = contextData.weekNumber;
const currentYear = contextData.year;

// Build a set of reporters who already got reminders this week
const remindedThisWeek = new Set();

sheetData.forEach(row => {
  const rowData = row.json;
  if (rowData.Year == currentYear && rowData.WeekNumber == currentWeek) {
    remindedThisWeek.add(rowData.ReporterName);
  }
});

// Filter to only reporters who need reminders
const reportersNeedingReminder = inactiveReporters.filter(
  name => !remindedThisWeek.has(name)
);

// If no one needs reminders, stop
if (reportersNeedingReminder.length === 0) {
  return [];
}

// Create one item per reporter needing reminder
return reportersNeedingReminder.map(reporterName => ({
  json: {
    reporterName: reporterName,
    reporterEmail: contextData.reporterEmails[reporterName],
    bossEmails: contextData.bossEmails,
    currentDay: contextData.currentDay,
    reminderType: contextData.reminderType,
    mondayDate: contextData.mondayDate,
    todayDate: contextData.todayDate,
    weekNumber: contextData.weekNumber,
    year: contextData.year
  }
}));

// Build Email Content
return items.map(item => {
  const reporterName = item.json.reporterName;
  const reporterEmail = item.json.reporterEmail;
  const bossEmails = item.json.bossEmails || [];
  const currentDay = item.json.currentDay;
  const reminderType = item.json.reminderType;
  const mondayDate = item.json.mondayDate;
  const todayDate = item.json.todayDate;

  const emailSubject = `[Action Required] Weekly Activity Update - ${currentDay} ${reminderType}`;

  const emailBodyHTML = `
    <div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #333;">
      <p>Hi <strong>${reporterName}</strong>,</p>

      <p>This is a <strong>${reminderType.toLowerCase()}</strong> regarding your weekly Jira activity updates.</p>

      <p>We noticed you haven't had any assigned issues updated from <strong>Monday (${mondayDate})</strong> through today <strong>(${currentDay}, ${todayDate})</strong>.</p>

      <div style="background-color: #f8f9fa; border-left: 4px solid #0066cc; padding: 15px; margin: 20px 0;">
        <h3 style="margin-top: 0; color: #0066cc;">📋 Action Required:</h3>
        <p style="margin-bottom: 0;">Please update your work activities in Jira by <strong>end of day today</strong> to ensure accurate weekly reporting.</p>
      </div>

      <h3 style="color: #0066cc;">🔍 What to update:</h3>
      <ul style="margin-top: 10px;">
        <li>Tasks accomplished</li>
        <li>Issues worked on</li>
        <li>Progress on assigned tickets</li>
        <li>Any blockers or challenges</li>
      </ul>

      <h3 style="color: #0066cc;">❓ Need Help?</h3>
      <p>If you have any questions about logging activities or if there are extenuating circumstances, please reach out directly.</p>

      <p style="margin-top: 30px;">Thank you for your prompt attention to this matter.</p>

      <p style="margin-top: 20px;">
        <strong>Best regards,</strong><br>
        Data Team Management
      </p>

      <hr style="border: none; border-top: 1px solid #ddd; margin: 30px 0;">
      <p style="font-size: 12px; color: #777;">
      </p>
    </div>
  `;

  return {
    json: {
      reporterName: reporterName,
      reporterEmail: reporterEmail,
      bossEmails: bossEmails,
      emailSubject: emailSubject,
      emailBodyHTML: emailBodyHTML,
      ccEmails: bossEmails.join(','),
      currentDay: currentDay,
      reminderType: reminderType,
      mondayDate: mondayDate,
      todayDate: todayDate,
      weekNumber: item.json.weekNumber,
      year: item.json.year
    }
  };
});
